/* Presentation settings only. Geographic classification and renderer stay in their own modules. */
window.Cartography={
 config:null,defaults:null,
 async load(){const r=await fetch('./cartography.json');if(!r.ok)throw Error('지도 표현 설정을 읽을 수 없습니다.');this.defaults=this.validate(await r.json());this.config=structuredClone(this.defaults)},
 validate(input){
 input.appearance??={mode:'standard',roofs:true,windows:true,wallColor:'#eee4cc',roofColor:'#cc8658',windowColor:'#537c77'};if(!['standard','miniature'].includes(input.appearance.mode)||typeof input.appearance.roofs!=='boolean'||typeof input.appearance.windows!=='boolean')throw Error('잘못된 미니어처 설정');
 const ranges={'terrain.exaggeration':[0,3],'terrain.shade':[0,1],'buildings.opacity':[0,1],'farmland.opacity':[0,1],'farmland.patternSpacing':[4,16],'forest.heightScale':[.5,2],'forest.widthScale':[.5,2],'forest.density':[.25,2],'forest.maxTrees':[0,1800],'forest.minZoom':[13,18]};
 if(input.version!==1)throw Error('설정 버전이 맞지 않습니다.');
 for(const [path,[lo,hi]] of Object.entries(ranges)){const [a,b]=path.split('.');const n=input[a]?.[b];if(typeof n!=='number'||!Number.isFinite(n)||n<lo||n>hi)throw Error('잘못된 설정: '+path)}
 for(const path of ['appearance.wallColor','appearance.roofColor','appearance.windowColor','buildings.lowColor','buildings.highColor','farmland.color','farmland.patternColor','farmland.boundaryColor','forest.color','forest.crownColor','forest.trunkColor']){const [a,b]=path.split('.');if(!/^#[0-9a-f]{6}$/i.test(input[a]?.[b]))throw Error('잘못된 색상: '+path)}
 for(const [a,b] of [['terrain','enabled'],['buildings','enabled'],['forest','trees']])if(typeof input[a]?.[b]!=='boolean')throw Error('잘못된 표시 설정');
 if(!['rows','grid','none'].includes(input.farmland.pattern)||!['cone','round'].includes(input.forest.shape))throw Error('지원하지 않는 표현 방식');return input;
 },
 mount(map){
 const panel=document.getElementById('cartography-fields');
 const groups=[['미니어처',[['appearance.mode','표현 모드','select',['standard','기본 지도','miniature','미니어처']],['appearance.roofs','경사지붕','checkbox'],['appearance.windows','창문 표시','checkbox'],['appearance.wallColor','외벽 색','color'],['appearance.roofColor','지붕 색','color'],['appearance.windowColor','창문 색','color']]],['산·언덕',[['terrain.exaggeration','높이 배율','range',0,3,.1],['terrain.shade','음영 강도','range',0,1,.05]]],['건물',[['buildings.lowColor','낮은 건물 색','color'],['buildings.highColor','높은 건물 색','color'],['buildings.opacity','불투명도','range',0,1,.05]]],['농경지 · 논·밭 통합',[['farmland.color','바탕색','color'],['farmland.pattern','패턴','select',['rows','사선 고랑','grid','격자','none','없음']],['farmland.patternColor','패턴 색','color'],['farmland.patternSpacing','패턴 간격','range',4,16,2],['farmland.boundaryColor','경계 색','color']]],['숲',[['forest.color','숲 바탕색','color'],['forest.trees','입체 나무 표시','checkbox'],['forest.shape','나무 모양','select',['cone','원뿔','round','둥근 수관']],['forest.crownColor','수관 색','color'],['forest.trunkColor','줄기 색','color'],['forest.heightScale','나무 높이 배율','range',.5,2,.1],['forest.widthScale','수관 너비 배율','range',.5,2,.1],['forest.density','나무 밀도 배율','range',.25,2,.25],['forest.maxTrees','최대 나무 수','range',0,1800,100],['forest.minZoom','나무 표시 줌','range',13,18,1]]]];
 const get=path=>path.split('.').reduce((o,k)=>o[k],this.config);
 const refresh=()=>panel.querySelectorAll('[data-setting]').forEach(el=>{const v=get(el.dataset.setting);if(el.type==='checkbox')el.checked=v;else el.value=v;const out=el.parentElement.querySelector('output');if(out)out.textContent=v});
 for(const [title,fields] of groups){const set=document.createElement('fieldset');const legend=document.createElement('legend');legend.textContent=title;set.append(legend);for(const [path,label,type,min,max,step] of fields){const row=document.createElement('label');row.className='carto-field';const name=document.createElement('span');name.textContent=label;const el=document.createElement(type==='select'?'select':'input');el.dataset.setting=path;if(type==='select'){for(let i=0;i<min.length;i+=2){const o=document.createElement('option');o.value=min[i];o.textContent=min[i+1];el.append(o)}}else {el.type=type;if(type==='range'){el.min=min;el.max=max;el.step=step;row.append(document.createElement('output'))}}row.prepend(name);row.append(el);el.addEventListener('input',()=>{const [a,b]=path.split('.');this.config[a][b]=type==='checkbox'?el.checked:type==='range'?Number(el.value):el.value;refresh();this.apply(map)});set.append(row)}panel.append(set)}
 document.getElementById('cartography-reset').onclick=()=>{this.config=structuredClone(this.defaults);refresh();this.apply(map)};
 document.getElementById('cartography-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(this.config,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cartography.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 this.refresh=refresh;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{this.config.appearance.mode=b.dataset.mode;refresh();this.apply(map);if(b.dataset.mode==='miniature')map.easeTo({pitch:55,bearing:-25,duration:700})});document.getElementById('miniature-namsan').onclick=()=>{this.config.appearance.mode='miniature';refresh();this.apply(map);document.getElementById('location').textContent='남산 · 미니어처';map.flyTo({center:[126.9845,37.5535],zoom:16.3,pitch:55,bearing:-25,duration:1300})};refresh();this.apply(map);
 },
 apply(map){const c=this.config;document.getElementById('terrain').checked=c.terrain.enabled;document.getElementById('buildings').checked=c.buildings.enabled;
 map.setTerrain(c.terrain.enabled?{source:'terrain-dem',exaggeration:c.terrain.exaggeration}:null);
 map.setLayoutProperty('terrain-hillshade','visibility',c.terrain.enabled?'visible':'none');map.setPaintProperty('terrain-hillshade','hillshade-exaggeration',c.terrain.shade);
 map.setLayoutProperty('building-3d','visibility',c.buildings.enabled?'visible':'none');map.setPaintProperty('building-3d','fill-extrusion-color',['interpolate',['linear'],['coalesce',['get','render_height'],6],0,c.buildings.lowColor,300,c.buildings.highColor]);map.setPaintProperty('building-3d','fill-extrusion-opacity',c.buildings.opacity);
 const wood=map.getLayer('landcover_wood');if(wood)map.setPaintProperty(wood.id,'fill-color',c.forest.color);
 document.querySelector('.legend i').style.background=`linear-gradient(90deg,${c.buildings.lowColor},${c.buildings.highColor})`;
 MiniatureStyle.apply(map);map.fire('cartographychange');map.triggerRepaint();
 }
};
